#include "KS/SRC/entity.h"

void anim_id_manager::purge()
{
  labels.resize(0);
  label_map.clear();
  // pre-defined anim ids
  #define MAC(a) anim_id( #a );
  #include "anim_ids.h"
  #undef MAC
  // NEW biped anim ids
  #define MAC(a,b) anim_id( #a, b );
  #include "biped_ids.h"
  #undef MAC
}
